import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, RefreshCw, TrendingUp, Loader, Youtube, X, Video } from 'lucide-react';
import { fetchTrendingVideos, searchYouTube, clearYouTubeCache, type YouTubeVideo } from '@/services/youtubeService';
import { fetchPopularPexelsVideos, searchPexels, clearPexelsCache, type PexelsVideo } from '@/services/pexelsService';
import YouTubeVideoCard from './YouTubeVideoCard';
import { YouTubeModalPlayer, PexelsModalPlayer } from '@/components/YouTubePlayer';
import EmptyState from '@/components/EmptyState';

type VideoSource = 'youtube' | 'pexels';
type FeedVideo = YouTubeVideo | PexelsVideo;

export default function YouTubeFeed() {
  const [videoSource, setVideoSource] = useState<VideoSource>('youtube');
  const [videos, setVideos] = useState<FeedVideo[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [error, setError] = useState('');
  const [activeVideo, setActiveVideo] = useState<FeedVideo | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const loadVideos = async () => {
    setLoading(true);
    setError('');
    try {
      let data: FeedVideo[];
      if (videoSource === 'youtube') {
        data = await fetchTrendingVideos('US', 16);
      } else {
        data = await fetchPopularPexelsVideos(16);
      }
      setVideos(data);
    } catch {
      setError('Failed to load videos');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!searchQuery.trim()) { loadVideos(); return; }
    setLoading(true);
    setError('');
    try {
      let data: FeedVideo[];
      if (videoSource === 'youtube') {
        data = await searchYouTube(searchQuery.trim(), 16);
      } else {
        data = await searchPexels(searchQuery.trim(), 16);
      }
      setVideos(data);
    } catch {
      setError('Search failed');
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = () => {
    if (videoSource === 'youtube') clearYouTubeCache();
    else clearPexelsCache();
    if (searchQuery.trim()) { handleSearch(); } else { loadVideos(); }
  };

  useEffect(() => { loadVideos(); }, [videoSource]);

  return (
    <div className="h-full flex flex-col bg-[#0d0d0d]">
      {/* Header */}
      <div className="shrink-0 px-4 py-3 border-b border-[#1a1a1a] space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${videoSource === 'youtube' ? 'bg-red-600/20' : 'bg-blue-600/20'}`}>
              {videoSource === 'youtube' ? (
                <Youtube size={18} className="text-red-500" />
              ) : (
                <Video size={18} className="text-blue-500" />
              )}
            </div>
            <div>
              <h2 className="text-sm font-semibold text-white">Videos</h2>
              <p className="text-[10px] text-[#8D8D8D]">
                {searchQuery ? `Search: "${searchQuery}"` : (videoSource === 'youtube' ? 'YouTube Trending' : 'Pexels Popular')}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {/* Source toggle */}
            <div className="flex bg-[#1a1a1a] rounded-lg p-1">
              <button
                type="button"
                onClick={() => setVideoSource('youtube')}
                className={`px-2 py-1 rounded-md text-xs font-medium transition-all ${videoSource === 'youtube' ? 'bg-red-600 text-white' : 'text-[#8D8D8D] hover:text-white'}`}
              >
                YouTube
              </button>
              <button
                type="button"
                onClick={() => setVideoSource('pexels')}
                className={`px-2 py-1 rounded-md text-xs font-medium transition-all ${videoSource === 'pexels' ? 'bg-blue-600 text-white' : 'text-[#8D8D8D] hover:text-white'}`}
              >
                Pexels
              </button>
            </div>
            <button
              type="button"
              onClick={handleRefresh}
              className="p-2 rounded-lg hover:bg-[#1a1a1a] text-[#8D8D8D]"
              aria-label="Refresh feed"
            >
              <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
            </button>
          </div>
        </div>

        {/* Search */}
        <form onSubmit={handleSearch} className="relative">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
          <input
            ref={searchInputRef}
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search videos..."
            aria-label="Search videos"
            className="w-full bg-[#1a1a1a] text-white pl-9 pr-9 py-2.5 rounded-xl text-sm placeholder:text-[#8D8D8D] focus:outline-none focus:ring-2 focus:ring-red-500/50"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => {
                setSearchQuery('');
                loadVideos();
              }}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-[#8D8D8D] hover:text-white"
              aria-label="Clear search"
            >
              <X size={14} />
            </button>
          )}
        </form>

      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading && videos.length === 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="bg-[#1a1a1a] rounded-xl overflow-hidden border border-[#2a2a2a]">
                <div className="aspect-video bg-[#222] animate-pulse" />
                <div className="p-3 space-y-2">
                  <div className="h-4 bg-[#222] rounded animate-pulse w-3/4" />
                  <div className="h-3 bg-[#222] rounded animate-pulse w-1/2" />
                </div>
              </div>
            ))}
          </div>
        ) : error && videos.length === 0 ? (
          <EmptyState
            icon={TrendingUp}
            title="No videos found"
            description={error}
            action={
              <button
                type="button"
                onClick={handleRefresh}
                className="px-4 py-2 bg-[#00C300] text-white rounded-full text-sm font-medium"
              >
                Try again
              </button>
            }
          />
        ) : videos.length === 0 ? (
          <EmptyState
            icon={Youtube}
            title="No videos yet"
            description="Add a YouTube API key to see trending videos, or search for content."
          />
        ) : (
          <>
            <div className="flex items-center gap-2 mb-4">
              <TrendingUp size={14} className="text-red-500" />
              <span className="text-xs font-medium text-[#8D8D8D] uppercase tracking-wider">
                {searchQuery ? 'Search Results' : 'Trending Videos'}
              </span>
              {loading && <Loader size={14} className="animate-spin text-[#8D8D8D]" />}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {videos.map((video, index) => (
                <motion.div
                  key={video.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.04 }}
                >
                  <YouTubeVideoCard
                    video={video}
                    index={index}
                    onPlay={setActiveVideo}
                  />
                </motion.div>
              ))}
            </div>
          </>
        )}
      </div>

      {/* In-app modal player ΓÇö no external links */}
      <AnimatePresence>
        {activeVideo && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            {'channelTitle' in activeVideo ? (
              <YouTubeModalPlayer
                videoId={activeVideo.id as string}
                title={activeVideo.title}
                channelTitle={activeVideo.channelTitle}
                onClose={() => setActiveVideo(null)}
              />
            ) : (
              <PexelsModalPlayer
                video={activeVideo as PexelsVideo}
                onClose={() => setActiveVideo(null)}
              />
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

