import { useState, useRef, useEffect, useCallback } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft, Camera, QrCode, ChevronRight, Edit2, MessageCircle,
  Link2, Copy, Check, Share2, MapPin, Globe, Phone, Mail, Ban,
  UserPlus, Loader, ImagePlus, Settings, Shield, Video, Flag, Star, Users
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useAuth } from '@/context/AuthContext';
import { useFriendStore } from '@/store/useFriendStore';
import { useGroupStore } from '@/store/useGroupStore';
import { isFirestoreAvailable, COLLECTIONS, getDocById, queryCollection, subscribeToDoc, subscribeToCollection } from '@/lib/firestore';
import { updateUserProfile } from '@/lib/supabaseAuth';
import { formatLastSeen } from '@/lib/timeUtils';
import { uploadMediaBlob } from '@/lib/storage';
import { buildGagaChatUri, buildGagaChatWebUrl, getDefaultAvatar, sanitizeMediaUrl } from '@/lib/utils';
import { where, orderBy, limit } from '@/lib/firestore';
import { toast } from 'sonner';
import type { TimelinePost, User, GroupData, FriendRequest, SentRequest, Chat } from '@/types';

type FriendRequestWithAliases = Partial<FriendRequest & SentRequest> & {
  to_user_id?: string;
  toUserId?: string;
  receiver_id?: string;
  receiverId?: string;
  from_user_id?: string;
  fromUserId?: string;
  sender_id?: string;
  senderId?: string;
};

// QR Code SVG component
function QRCodeSVG({ data, size = 180 }: { data: string; size?: number }) {
  const [svg, setSvg] = useState('');
  useEffect(() => {
    import('qrcode').then((QR) => {
      QR.toString(data, { type: 'svg', width: size, margin: 2, color: { dark: '#111111', light: '#ffffff' } })
        .then(setSvg).catch(() => setSvg(''));
    });
  }, [data, size]);
  if (!svg) return <div className={`w-[${size}px] h-[${size}px] bg-gray-100 rounded-lg animate-pulse`} />;
  return <div dangerouslySetInnerHTML={{ __html: svg }} className="w-full h-full flex items-center justify-center" />;
}

// Wallet icon component
function WalletIcon(props: { size: number; strokeWidth: number; className: string }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={props.size} height={props.size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={props.strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={props.className}>
      <path d="M21 12V7H5a2 2 0 0 1 0-4h14v4" /><path d="M3 5v14a2 2 0 0 0 2 2h16v-5" /><path d="M18 12a2 2 0 0 0 0 4h4v-4Z" />
    </svg>
  );
}

export default function ProfilePage() {
  const navigate = useNavigate();
  const _params = useParams();
  const viewUserId = (_params as { userId?: string }).userId;
  const { user, setUser } = useAuthStore();
  const { logout } = useAuth();
  const {
    getUserById, sendRequest, getFriendStatus, getMutualFriendsCount,
    cancelRequest, acceptRequest, rejectRequest, blockUser, unblockUser,
    reportUser, removeFriend, sentRequests, requests, toggleFavorite
  } = useFriendStore();
  const { groups } = useGroupStore();
  const [viewUser, setViewUser] = useState<User | null>(null);
  const [loadingViewUser, setLoadingViewUser] = useState(false);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showQr, setShowQr] = useState(false);
  const [showAvatarViewer, setShowAvatarViewer] = useState(false);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  const [copied, setCopied] = useState(false);
  const [posts, setPosts] = useState<TimelinePost[]>([]);
  const [loadingPosts, setLoadingPosts] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [friendStatus, setFriendStatus] = useState<string>('not_friends');
  const [mutualCount, setMutualCount] = useState(0);
  const [mutualGroups, setMutualGroups] = useState<Chat[]>([]);
  const [loadingStatus, setLoadingStatus] = useState(false);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportReason, setReportReason] = useState('');
  const [reportDetails, setReportDetails] = useState('');
  const [processingAction, setProcessingAction] = useState(false);
  const [isFavorited, setIsFavorited] = useState(false);

  const isViewingOther = !!viewUserId;
  const displayUserNullable = viewUser || user;
  const targetUserId = viewUserId || user?.id;

  // Load view user when viewing another profile
  useEffect(() => {
    if (!viewUserId) { setViewUser(null); return; }
    let cancelled = false;
    setLoadingViewUser(true);
    getUserById(viewUserId)
      .then((u) => {
        if (!cancelled) {
          setViewUser(u);
          setLoadingViewUser(false);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setViewUser(null);
          setLoadingViewUser(false);
        }
      });
    return () => { cancelled = true; };
  }, [viewUserId, getUserById]);

  // Load friend status and mutual count when viewing another user
  useEffect(() => {
    if (!isViewingOther || !user?.id || !viewUserId) return;
    setLoadingStatus(true);
    const loadStatus = async () => {
      try {
        const status = await getFriendStatus(user.id, viewUserId);
        setFriendStatus(status);
        const mutual = await getMutualFriendsCount(user.id, viewUserId);
        setMutualCount(mutual);
        const fav = user.favorites?.includes(viewUserId) || false;
        setIsFavorited(fav);
      } catch { /* noop */ } finally {
        setLoadingStatus(false);
      }
    };
    loadStatus();
  }, [isViewingOther, user?.id, viewUserId, getFriendStatus, getMutualFriendsCount, user?.favorites]);

  // Compute mutual groups when viewing another user
  useEffect(() => {
    if (!isViewingOther || !user?.id || !viewUserId) return;
    const shared = groups.filter(g => {
      const participants = g.participants || [];
      return participants.includes(user!.id) && participants.includes(viewUserId);
    });
    setMutualGroups(shared);
  }, [isViewingOther, user, user?.id, viewUserId, groups]);

  // Real-time sync: subscribe to user profile changes (Firestore only, skip if unavailable)
  useEffect(() => {
    if (!isFirestoreAvailable() || !targetUserId) return;
    // Only sync from Firestore when viewing another user ΓÇö own profile comes from Supabase via useAuthStore
    if (!viewUserId) return;
    const fetchProfile = async () => {
      try {
        const data = await getDocById(COLLECTIONS.USERS, targetUserId);
        if (!data) return;
        const updatedUser = {
          id: data.id,
          name: data.name || 'User',
          displayName: data.displayName || data.name || 'User',
          username: data.username || '',
          email: data.email || '',
          phone: data.phone || '',
          avatar: data.avatar || '',
          status: data.status || 'offline',
          statusMessage: data.statusMessage || '',
          lastSeen: data.lastSeen ? new Date(data.lastSeen) : null,
          coins: data.coins || 0,
          savedPosts: data.savedPosts || [],
          blockedUsers: data.blockedUsers || [],
          favorites: data.favorites || [],
          friends: data.friends || [],
          bio: data.bio || '',
          location: data.location || '',
          website: data.website || '',
          verified: data.verified || false,
        } as User;
        if (viewUserId) {
          setViewUser(updatedUser);
        } else if (user?.id === targetUserId) {
          setUser(updatedUser);
        }
      } catch {
        // Silently ignore ΓÇö user may not exist or firestore may be down
      }
    };
    fetchProfile();
    const unsubscribe = subscribeToDoc(COLLECTIONS.USERS, targetUserId, (data) => {
      if (!data) return;
      const updatedUser = {
        id: data.id,
        name: data.name || 'User',
        displayName: data.displayName || data.name || 'User',
        username: data.username || '',
        email: data.email || '',
        phone: data.phone || '',
        avatar: data.avatar || '',
        status: data.status || 'offline',
        statusMessage: data.statusMessage || '',
        lastSeen: data.lastSeen ? new Date(data.lastSeen) : null,
        coins: data.coins || 0,
        savedPosts: data.savedPosts || [],
        blockedUsers: data.blockedUsers || [],
        favorites: data.favorites || [],
        friends: data.friends || [],
        bio: data.bio || '',
        location: data.location || '',
        website: data.website || '',
        verified: data.verified || false,
      } as User;
      if (viewUserId) {
        setViewUser(updatedUser);
      } else if (user?.id === targetUserId) {
        setUser(updatedUser);
      }
    });
    return () => unsubscribe();
  }, [targetUserId, viewUserId, user?.id, setUser]);

  // Form states
  const [form, setForm] = useState({
    displayName: user?.displayName || '',
    name: user?.name || '',
    bio: user?.bio || '',
    statusMessage: user?.statusMessage || '',
    location: user?.location || '',
    website: user?.website || '',
    phone: user?.phone || '',
  });

  // Sync form when user changes
  useEffect(() => {
    if (user) {
      setForm({
        displayName: user.displayName || '',
        name: user.name || '',
        bio: user.bio || '',
        statusMessage: user.statusMessage || '',
        location: user.location || '',
        website: user.website || '',
        phone: user.phone || '',
      });
    }
  }, [user]);

  const fetchPosts = useCallback(async () => {
    if (!targetUserId) return;
    setLoadingPosts(true);
    try {
      if (isFirestoreAvailable()) {
        const data = await queryCollection(COLLECTIONS.POSTS, [
          where('userId', '==', targetUserId),
          orderBy('timestamp', 'desc'),
          limit(30),
        ]);
        let list: TimelinePost[] = data.map((d: Record<string, unknown>) => ({
          id: (d.id as string) || '', userId: (d.userId as string) || '', content: (d.content as string) || '',
          images: (d.images as string[]) || [], likes: (d.likes as string[]) || [], comments: (d.comments as any[]) || [],
          shares: (d.shares as string[]) || [], timestamp: d.timestamp ? new Date(d.timestamp as string) : new Date(),
          visibility: (d.visibility as TimelinePost['visibility']) || 'public',
        }));
        // Visibility filter when viewing another user's profile
        if (isViewingOther && user?.id) {
          const isFriend = friendStatus === 'friends';
          list = list.filter((post) => {
            if (post.visibility === 'private') return false;
            if (post.visibility === 'friends' && !isFriend) return false;
            return true;
          });
        }
        setPosts(list);
      }
    } catch { /* noop */ }
    setLoadingPosts(false);
  }, [targetUserId, isViewingOther, user?.id, friendStatus]);

  useEffect(() => {
    fetchPosts();
  }, [fetchPosts]);

  useEffect(() => {
    if (!isFirestoreAvailable() || !targetUserId) return;
    const unsubscribe = subscribeToCollection(COLLECTIONS.POSTS, [
      where('userId', '==', targetUserId),
      orderBy('timestamp', 'desc'),
    ], () => fetchPosts());
    return () => unsubscribe();
  }, [targetUserId, fetchPosts]);

  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    try {
      const updated = { ...user, ...form };

      // Update in Supabase
      const success = await updateUserProfile(user.id, form);
      if (success) {
        // Update app state
        setUser(updated);
        toast.success('Profile updated');
        setEditing(false);
      } else {
        toast.error('Failed to update profile');
      }
    } catch { 
      toast.error('Failed to update profile');
    }
    setSaving(false);
  };

  const handleAvatarUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;
    setUploadingAvatar(true);
    try {
      // Upload to storage (Cloudinary or similar)
      const url = await uploadMediaBlob({ kind: 'avatars', userId: user.id, file });

      // Update in Supabase
      const updatedUser = { ...user, avatar: url };
      const success = await updateUserProfile(user.id, { avatar: url });
      if (success) {
        // Update app state
        setUser(updatedUser);
        toast.success('Avatar updated');
      } else {
        toast.error('Failed to update avatar');
      }
    } catch { 
      toast.error('Failed to update avatar');
    } finally {
      setUploadingAvatar(false);
    }
  };

  const handleCopyLink = async () => {
    const link = displayUser ? buildGagaChatWebUrl(displayUser.id) : '';
    try {
      await navigator.clipboard.writeText(link);
      setCopied(true);
      toast.success('Profile link copied');
      const t = setTimeout(() => setCopied(false), 2000);
      return () => clearTimeout(t);
    } catch { toast.error('Failed to copy'); }
  };

  const handleShare = async () => {
    const link = displayUser ? buildGagaChatWebUrl(displayUser.id) : '';
    try {
      if (navigator.share) {
        await navigator.share({ title: `Add ${displayUser?.name} on GaGa Chat`, text: `Connect with me on GaGa Chat!`, url: link });
      } else {
        await handleCopyLink();
      }
    } catch { /* cancelled */ }
  };

  const handleToggleFavorite = async () => {
    if (!user?.id || !displayUser?.id) return;
    setProcessingAction(true);
    try {
      await toggleFavorite(displayUser.id, user.id, user.favorites || []);
      setIsFavorited(!isFavorited);
      toast.success(isFavorited ? 'Removed from favorites' : 'Added to favorites');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const profileLink = displayUserNullable ? buildGagaChatWebUrl(displayUserNullable.id) : '';
  const qrCodeData = displayUserNullable ? buildGagaChatUri(displayUserNullable.id) : '';

  // Friend action helpers
  const findSentRequest = (toUserId: string) => {
    return sentRequests.find((r: FriendRequestWithAliases) =>
      (r.toUserId === toUserId) || (r.to_user_id === toUserId) ||
      (r.receiverId === toUserId) || (r.receiver_id === toUserId)
    );
  };

  const findReceivedRequest = (fromUserId: string) => {
    return requests.find((r: FriendRequestWithAliases) =>
      (r.from === fromUserId) || (r.fromUserId === fromUserId) || (r.from_user_id === fromUserId) ||
      (r.senderId === fromUserId) || (r.sender_id === fromUserId)
    );
  };

  const handleAddFriend = async () => {
    if (!user?.id || !displayUser?.id) return;
    setProcessingAction(true);
    try {
      await sendRequest(displayUser.id, user.id);
      toast.success('Friend request sent');
      setFriendStatus('request_sent');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleCancelRequest = async () => {
    if (!user?.id || !displayUser?.id) return;
    const req = findSentRequest(displayUser.id);
    if (!req) return;
    setProcessingAction(true);
    try {
      await cancelRequest(req.id);
      toast.success('Friend request cancelled');
      setFriendStatus('not_friends');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleAcceptRequest = async () => {
    if (!user?.id || !displayUser?.id) return;
    const req = findReceivedRequest(displayUser.id);
    if (!req) return;
    setProcessingAction(true);
    try {
      await acceptRequest(req.id);
      toast.success('Friend request accepted');
      setFriendStatus('friends');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleRejectRequest = async () => {
    if (!user?.id || !displayUser?.id) return;
    const req = findReceivedRequest(displayUser.id);
    if (!req) return;
    setProcessingAction(true);
    try {
      await rejectRequest(req.id);
      toast.success('Friend request declined');
      setFriendStatus('not_friends');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleRemoveFriend = async () => {
    if (!user?.id || !displayUser?.id) return;
    setProcessingAction(true);
    try {
      await removeFriend(displayUser.id, user.id);
      toast.success('Friend removed');
      setFriendStatus('not_friends');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleBlockUser = async () => {
    if (!user?.id || !displayUser?.id) return;
    setProcessingAction(true);
    try {
      await blockUser(displayUser.id, user.id);
      toast.success('User blocked');
      setFriendStatus('blocked');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleUnblockUser = async () => {
    if (!user?.id || !displayUser?.id) return;
    setProcessingAction(true);
    try {
      await unblockUser(displayUser.id, user.id);
      toast.success('User unblocked');
      setFriendStatus('not_friends');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const handleReportSubmit = async () => {
    if (!user?.id || !displayUser?.id || !reportReason) return;
    setProcessingAction(true);
    try {
      await reportUser({ reporterId: user.id, reportedId: displayUser.id, reason: reportReason, details: reportDetails });
      toast.success('Report submitted');
      setShowReportModal(false);
      setReportReason('');
      setReportDetails('');
    } catch { /* noop */ }
    setProcessingAction(false);
  };

  const reportOptions = ['Spam', 'Harassment', 'Inappropriate content', 'Fake account', 'Other'];

  if (loadingViewUser || (!displayUserNullable && isViewingOther)) {
    return (
      <div className="min-h-[100dvh] bg-[#F5F5F5] flex items-center justify-center">
        <Loader size={32} className="text-[#00C300] animate-spin" />
      </div>
    );
  }

  if (!displayUserNullable) {
    return (
      <div className="min-h-[100dvh] bg-[#F5F5F5] flex items-center justify-center">
        <Loader size={32} className="text-[#00C300] animate-spin" />
      </div>
    );
  }

  // After guards, displayUser is guaranteed non-null
  const displayUser = displayUserNullable;

  const renderActionButtons = () => {
    if (loadingStatus) {
      return <Loader size={20} className="text-[#00C300] animate-spin" />;
    }

    switch (friendStatus) {
      case 'not_friends':
        return (
          <div className="flex gap-2 flex-wrap justify-center">
            <button type="button" onClick={handleAddFriend} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#00C300] rounded-full text-sm font-medium text-white active:bg-[#00A300] transition-colors disabled:opacity-50">
              <UserPlus size={14} /> Add Friend
            </button>
            <button type="button" onClick={handleBlockUser} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors disabled:opacity-50">
              <Ban size={14} /> Block
            </button>
            <button type="button" onClick={() => setShowReportModal(true)} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors disabled:opacity-50">
              <Flag size={14} /> Report
            </button>
          </div>
        );
      case 'request_sent':
        return (
          <div className="flex gap-2 flex-wrap justify-center">
            <button type="button" onClick={handleCancelRequest} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#FF9800] rounded-full text-sm font-medium text-white active:bg-[#F57C00] transition-colors disabled:opacity-50">
              <Ban size={14} /> Cancel Request
            </button>
            <button type="button" onClick={handleBlockUser} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors disabled:opacity-50">
              <Ban size={14} /> Block
            </button>
          </div>
        );
      case 'request_received':
        return (
          <div className="flex gap-2 flex-wrap justify-center">
            <button type="button" onClick={handleAcceptRequest} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#00C300] rounded-full text-sm font-medium text-white active:bg-[#00A300] transition-colors disabled:opacity-50">
              <Check size={14} /> Accept Request
            </button>
            <button type="button" onClick={handleRejectRequest} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#FF3B30] rounded-full text-sm font-medium text-white active:bg-[#D32F2F] transition-colors disabled:opacity-50">
              <Ban size={14} /> Decline
            </button>
            <button type="button" onClick={handleBlockUser} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors disabled:opacity-50">
              <Ban size={14} /> Block
            </button>
          </div>
        );
      case 'friends':
        return (
          <div className="flex gap-2 flex-wrap justify-center">
            <button type="button" onClick={() => navigate(`/chat/${displayUser.id}`)} className="flex items-center gap-1.5 px-4 py-2 bg-[#00C300] rounded-full text-sm font-medium text-white active:bg-[#00A300] transition-colors">
              <MessageCircle size={14} /> Message
            </button>
            <button type="button" onClick={handleToggleFavorite} disabled={processingAction} className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-medium transition-colors disabled:opacity-50 ${isFavorited ? 'bg-yellow-100 text-yellow-700 active:bg-yellow-200' : 'bg-[#F5F5F5] text-[#111111] active:bg-[#EBEBEB]'}`}>
              <Star size={14} className={isFavorited ? 'fill-yellow-500 text-yellow-500' : ''} /> {isFavorited ? 'Favorited' : 'Favorite'}
            </button>
            <button type="button" onClick={() => navigate('/call', { state: { userId: displayUser.id, mode: 'voice' } })} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors">
              <Phone size={14} /> Call
            </button>
            <button type="button" onClick={() => navigate('/call', { state: { userId: displayUser.id, mode: 'video' } })} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors">
              <Video size={14} /> Video Call
            </button>
            <button type="button" onClick={handleRemoveFriend} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#FF3B30] rounded-full text-sm font-medium text-white active:bg-[#D32F2F] transition-colors disabled:opacity-50">
              <Ban size={14} /> Remove Friend
            </button>
            <button type="button" onClick={handleBlockUser} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors disabled:opacity-50">
              <Ban size={14} /> Block
            </button>
          </div>
        );
      case 'blocked':
        return (
          <div className="flex gap-2 flex-wrap justify-center">
            <button type="button" onClick={handleUnblockUser} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#00C300] rounded-full text-sm font-medium text-white active:bg-[#00A300] transition-colors disabled:opacity-50">
              <Check size={14} /> Unblock
            </button>
            <button type="button" onClick={() => setShowReportModal(true)} disabled={processingAction} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors disabled:opacity-50">
              <Flag size={14} /> Report
            </button>
          </div>
        );
      default:
        return (
          <div className="flex gap-2 flex-wrap justify-center">
            <span className="text-sm text-[#8D8D8D]">Unable to load actions</span>
          </div>
        );
    }
  };

  return (
    <div className="min-h-[100dvh] bg-[#F5F5F5]">
      {/* Header */}
      <div className="bg-white border-b border-[#EBEBEB]">
        <div className="flex items-center gap-3 p-4">
          <button type="button" onClick={() => navigate(-1)} className="p-2 -ml-2 active:bg-gray-100 rounded-full text-[#111111]">
            <ArrowLeft size={22} />
          </button>
          <h1 className="text-lg font-bold text-[#111111]">{isViewingOther ? displayUser.name || 'Profile' : 'Profile'}</h1>
          {!isViewingOther && (
            <button type="button" onClick={() => setEditing(!editing)} className="ml-auto p-2 active:bg-gray-100 rounded-full text-[#8D8D8D]">
              {editing ? <Ban size={18} /> : <Edit2 size={18} />}
            </button>
          )}
        </div>
      </div>

      {/* Profile Card */}
      <div className="bg-white pb-6 mb-4">
        <div className="flex flex-col items-center pt-6">
          {/* Avatar */}
          <div className="relative mb-3">
            <div
              className={`w-28 h-28 rounded-full bg-[#F5F5F5] flex items-center justify-center border-3 border-[#EBEBEB] overflow-hidden shadow-sm ${!isViewingOther ? 'cursor-pointer' : ''}`}
              onClick={() => {
                if (!isViewingOther) fileInputRef.current?.click();
                else if (sanitizeMediaUrl(displayUser.avatar)) setShowAvatarViewer(true);
              }}
            >
              {uploadingAvatar ? (
                <Loader size={32} className="text-[#00C300] animate-spin" />
              ) : sanitizeMediaUrl(displayUser.avatar) ? (
                <img src={sanitizeMediaUrl(displayUser.avatar)} className="w-full h-full object-cover" alt="User avatar" />
              ) : (
                <img src={getDefaultAvatar(displayUser.id || displayUser.name || 'U')} className="w-full h-full object-cover" alt="User avatar" />
              )}
            </div>
            {!isViewingOther && (
              <button type="button" onClick={() => fileInputRef.current?.click()}
                disabled={uploadingAvatar}
                className="absolute bottom-0 right-0 w-9 h-9 rounded-full bg-[#00C300] flex items-center justify-center border-2 border-white shadow-sm disabled:opacity-50"
              >
                {uploadingAvatar ? <Loader size={14} className="text-white animate-spin" /> : <Camera size={16} className="text-white" />}
              </button>
            )}
            <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleAvatarUpload} />
          </div>

          <div className="flex items-center gap-1">
            <h2 className="text-xl font-bold text-[#111111]">{displayUser.displayName || displayUser.name}</h2>
            {displayUser.verified && (
              <span className="text-[#00C300]">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M9 12l2 2 4-4" />
                  <circle cx="12" cy="12" r="10" />
                </svg>
              </span>
            )}
          </div>
          <p className="text-[#8D8D8D] text-sm">@{displayUser.username || 'user'}</p>
          {displayUser.statusMessage && <p className="text-[#111111] text-sm mt-1">{displayUser.statusMessage}</p>}
          {displayUser.bio && <p className="text-[#8D8D8D] text-sm mt-1 max-w-xs text-center">{displayUser.bio}</p>}

          {/* Online/Last Seen Status with privacy respect */}
          {displayUser.status && (
            <div className="flex items-center gap-1.5 mt-1">
              <span className={`w-2 h-2 rounded-full ${displayUser.status === 'online' ? 'bg-[#00C300]' : 'bg-[#8D8D8D]'}`} />
              <span className="text-[#8D8D8D] text-xs">
                {displayUser.status === 'online'
                  ? 'Online'
                  : (!isViewingOther || friendStatus === 'friends')
                    ? (displayUser.lastSeen ? `Last seen ${formatLastSeen(displayUser.lastSeen)}` : 'Offline')
                    : 'Offline'}
              </span>
            </div>
          )}

          {/* Location & Website badges */}
          <div className="flex items-center gap-3 mt-2">
            {displayUser.location && (
              <span className="flex items-center gap-1 text-[#8D8D8D] text-xs">
                <MapPin size={12} /> {displayUser.location}
              </span>
            )}
            {displayUser.website && (
              <a href={displayUser.website} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-[#00C300] text-xs hover:underline">
                <Globe size={12} /> Website
              </a>
            )}
          </div>

          {/* Stats */}
          <div className="flex items-center gap-8 mt-4 text-sm">
            <div className="text-center cursor-pointer" onClick={() => navigate('/contacts')}>
              <span className="text-[#111111] font-bold block">{(displayUser.friends || []).length}</span>
              <span className="text-[#8D8D8D] text-xs">Friends</span>
            </div>
            <div className="text-center">
              <span className="text-[#111111] font-bold block">{posts.length}</span>
              <span className="text-[#8D8D8D] text-xs">Posts</span>
            </div>
            <div className="text-center">
              <span className="text-[#111111] font-bold block">{(displayUser.coins || 0).toLocaleString()}</span>
              <span className="text-[#8D8D8D] text-xs">Coins</span>
            </div>
            {isViewingOther && (
              <div className="text-center">
                <span className="text-[#111111] font-bold block">{mutualCount}</span>
                <span className="text-[#8D8D8D] text-xs">Mutual</span>
              </div>
            )}
          </div>

          {/* Quick Actions */}
          <div className="flex gap-2 mt-4">
            {isViewingOther ? (
              renderActionButtons()
            ) : (
              <>
                <button type="button" onClick={handleCopyLink} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors">
                  {copied ? <Check size={14} className="text-[#00C300]" /> : <Copy size={14} />}
                  {copied ? 'Copied' : 'Copy Link'}
                </button>
                <button type="button" onClick={() => setShowQr(true)} className="flex items-center gap-1.5 px-4 py-2 bg-[#F5F5F5] rounded-full text-sm font-medium text-[#111111] active:bg-[#EBEBEB] transition-colors">
                  <QrCode size={14} /> QR Code
                </button>
                <button type="button" onClick={handleShare} className="flex items-center gap-1.5 px-4 py-2 bg-[#00C300] rounded-full text-sm font-medium text-white active:bg-[#00A300] transition-colors">
                  <Share2 size={14} /> Share
                </button>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Mutual Groups - when viewing another user */}
      {isViewingOther && mutualGroups.length > 0 && (
        <div className="bg-white border-y border-[#EBEBEB] p-4 mb-4">
          <div className="flex items-center gap-2 mb-3">
            <Users size={18} className="text-[#00C300]" />
            <h3 className="text-sm font-semibold text-[#111111]">Mutual Groups ({mutualGroups.length})</h3>
          </div>
          <div className="flex gap-3 overflow-x-auto scrollbar-hide">
            {mutualGroups.map(g => (
              <button
                type="button"
                key={g.id}
                onClick={() => navigate(`/group/${g.id}`)}
                className="flex items-center gap-2 min-w-[160px] p-2.5 bg-[#F5F5F5] rounded-xl text-left hover:bg-[#EBEBEB] transition-colors"
              >
                <div className="w-10 h-10 rounded-full bg-[#E8F5E9] flex items-center justify-center shrink-0 overflow-hidden">
                  {g.avatar ? (
                    <img src={sanitizeMediaUrl(g.avatar)} className="w-full h-full object-cover" alt="Group avatar" />
                  ) : (
                    <Users size={18} className="text-[#00C300]" />
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-[#111111] text-sm font-medium truncate">{g.name || 'Group'}</p>
                  <p className="text-[#8D8D8D] text-xs">{(g.participants || []).length} members</p>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Edit Form - only for current user */}
      <AnimatePresence>
        {editing && !isViewingOther && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="bg-white border-y border-[#EBEBEB] p-4 mb-4 space-y-3 overflow-hidden"
          >
            <h3 className="text-sm font-semibold text-[#111111] mb-2">Edit Profile</h3>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[#8D8D8D] text-xs mb-1 block">Name</label>
                <input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
                  className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]" />
              </div>
              <div>
                <label className="text-[#8D8D8D] text-xs mb-1 block">Display Name</label>
                <input value={form.displayName} onChange={e => setForm(f => ({ ...f, displayName: e.target.value }))}
                  className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]" />
              </div>
            </div>
            <div>
              <label className="text-[#8D8D8D] text-xs mb-1 block">Status Message</label>
              <input value={form.statusMessage} onChange={e => setForm(f => ({ ...f, statusMessage: e.target.value }))}
                className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]" />
            </div>
            <div>
              <label className="text-[#8D8D8D] text-xs mb-1 block">Bio</label>
              <textarea value={form.bio} onChange={e => setForm(f => ({ ...f, bio: e.target.value }))}
                className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300] resize-none min-h-[60px]"
                maxLength={160} />
              <p className="text-[#C7C7CC] text-[10px] text-right mt-0.5">{form.bio.length}/160</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[#8D8D8D] text-xs mb-1 block">Location</label>
                <input value={form.location} onChange={e => setForm(f => ({ ...f, location: e.target.value }))}
                  className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]" />
              </div>
              <div>
                <label className="text-[#8D8D8D] text-xs mb-1 block">Website</label>
                <input value={form.website} onChange={e => setForm(f => ({ ...f, website: e.target.value }))}
                  className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]" />
              </div>
            </div>
            <div>
              <label className="text-[#8D8D8D] text-xs mb-1 block">Phone</label>
              <input value={form.phone} onChange={e => setForm(f => ({ ...f, phone: e.target.value }))}
                className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]" />
            </div>
            <button type="button" onClick={handleSave}
              disabled={saving}
              className="w-full bg-[#00C300] hover:bg-[#00A300] text-white rounded-xl py-3 text-sm font-bold transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
            >
              {saving ? <Loader size={16} className="animate-spin" /> : <Check size={16} />}
              Save Changes
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Menu - only for own profile */}
      {!isViewingOther && (
        <div className="bg-white border-y border-[#EBEBEB] mb-4">
          {[
            { icon: QrCode, label: 'My QR Code', action: () => setShowQr(true) },
            { icon: WalletIcon, label: 'My Wallet', action: () => navigate('/wallet') },
            { icon: MessageCircle, label: 'Notifications', action: () => navigate('/notifications') },
            { icon: Shield, label: 'Privacy & Security', action: () => navigate('/privacy') },
            { icon: Settings, label: 'Settings', action: () => navigate('/settings') },
          ].map((item, idx, arr) => (
            <button type="button" key={item.label}
              onClick={item.action}
              className={`w-full flex items-center px-4 py-3.5 active:bg-gray-50 text-left ${idx !== arr.length - 1 ? 'border-b border-[#EBEBEB]' : ''}`}
            >
              <item.icon size={20} strokeWidth={1.5} className="text-[#111111] mr-3" />
              <span className="flex-1 text-[16px] text-[#111111]">{item.label}</span>
              <ChevronRight size={20} className="text-[#C7C7CC]" />
            </button>
          ))}
        </div>
      )}

      {/* Contact Info - only for own profile */}
      {!isViewingOther && (
        <div className="bg-white border-y border-[#EBEBEB] mb-4 p-4">
          <h3 className="text-sm font-semibold text-[#111111] mb-3">Contact Info</h3>
          <div className="space-y-3">
            {displayUser.email && (
              <div className="flex items-center gap-3">
                <Mail size={16} className="text-[#8D8D8D]" />
                <span className="text-[#111111] text-sm">{displayUser.email}</span>
              </div>
            )}
            {displayUser.phone && (
              <div className="flex items-center gap-3">
                <Phone size={16} className="text-[#8D8D8D]" />
                <span className="text-[#111111] text-sm">{displayUser.phone}</span>
              </div>
            )}
            <div className="flex items-center gap-3">
              <Link2 size={16} className="text-[#8D8D8D]" />
              <a
                href={profileLink}
                target="_blank"
                rel="noopener noreferrer"
                className="text-[#00C300] text-xs hover:underline truncate max-w-[200px]"
              >
                {profileLink}
              </a>
            </div>
          </div>
        </div>
      )}

      {/* Posts Grid */}
      <div className="bg-white p-4">
        <h3 className="text-sm font-semibold text-[#111111] mb-3">Posts</h3>
        {loadingPosts ? (
          <div className="flex justify-center py-8">
            <Loader size={20} className="animate-spin text-[#00C300]" />
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-1">
            {posts.map((post) => (
              <div key={post.id} className="aspect-square bg-[#F5F5F5] rounded-lg overflow-hidden">
                {post.images && post.images[0] ? (
                  <img src={post.images[0]} className="w-full h-full object-cover" alt="Post image" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center p-2">
                    <p className="text-[#8D8D8D] text-xs line-clamp-3">{post.content}</p>
                  </div>
                )}
              </div>
            ))}
            {posts.length === 0 && (
              <div className="col-span-3 py-12 text-center text-[#8D8D8D] text-sm">
                <ImagePlus size={24} className="mx-auto mb-2 text-[#EBEBEB]" />
                No posts yet
              </div>
            )}
          </div>
        )}
      </div>

      {/* Avatar Viewer Modal */}
      <AnimatePresence>
        {showAvatarViewer && sanitizeMediaUrl(displayUser.avatar) && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/90 z-[100] flex items-center justify-center"
            onClick={() => setShowAvatarViewer(false)}
          >
            <motion.img
              initial={{ scale: 0.8 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.8 }}
              src={sanitizeMediaUrl(displayUser.avatar)}
              className="max-w-[90%] max-h-[80%] object-contain rounded-2xl"
              alt="Avatar"
              onClick={(e) => e.stopPropagation()}
            />
            <button type="button" onClick={() => setShowAvatarViewer(false)}
              className="absolute top-4 right-4 p-2 bg-white/20 rounded-full text-white hover:bg-white/30"
            >
              <Ban size={24} />
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Logout - only for own profile */}
      {!isViewingOther && (
        <div className="p-4 mt-4">
          <button type="button" onClick={logout}
            className="w-full py-3 bg-[#FF3B30]/10 text-[#FF3B30] rounded-xl font-semibold text-sm active:bg-[#FF3B30]/20 transition-colors"
          >
            Log Out
          </button>
        </div>
      )}

      {/* QR Code Modal */}
      <AnimatePresence>
        {showQr && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4"
            onClick={() => setShowQr(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white rounded-3xl p-6 max-w-sm w-full"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold text-[#111111]">My QR Code</h2>
                <button type="button" onClick={() => setShowQr(false)} className="p-1 text-[#8D8D8D]"><Ban size={18} /></button>
              </div>
              <div className="bg-[#F5F5F5] rounded-2xl p-6 mb-4">
                <div className="w-52 h-52 mx-auto bg-white rounded-xl p-3">
                  <QRCodeSVG data={qrCodeData} size={200} />
                </div>
                <p className="text-center text-[#8D8D8D] text-xs mt-3">Scan to add {user?.name || 'you'} on GaGa Chat</p>
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={handleCopyLink} className="flex-1 flex items-center justify-center gap-2 py-3 bg-[#F5F5F5] text-[#111111] rounded-xl text-sm font-bold">
                  <Copy size={16} /> Copy Link
                </button>
                <button type="button" onClick={handleShare} className="flex-1 flex items-center justify-center gap-2 py-3 bg-[#00C300] text-white rounded-xl text-sm font-bold">
                  <Share2 size={16} /> Share
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Report Modal */}
      <AnimatePresence>
        {showReportModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4"
            onClick={() => setShowReportModal(false)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="bg-white rounded-3xl p-6 max-w-sm w-full"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold text-[#111111]">Report User</h2>
                <button type="button" onClick={() => setShowReportModal(false)} className="p-1 text-[#8D8D8D]"><Ban size={18} /></button>
              </div>
              <p className="text-[#8D8D8D] text-sm mb-3">Why are you reporting {displayUser.name}?</p>
              <div className="space-y-2 mb-3">
                {reportOptions.map((option) => (
                  <button type="button" key={option}
                    onClick={() => setReportReason(option)}
                    className={`w-full flex items-center justify-between px-4 py-2.5 rounded-xl text-sm transition-colors ${
                      reportReason === option ? 'bg-[#00C300]/10 text-[#00C300] font-medium' : 'bg-[#F5F5F5] text-[#111111]'
                    }`}
                  >
                    {option}
                    {reportReason === option && <Check size={16} />}
                  </button>
                ))}
              </div>
              <div className="mb-4">
                <label className="text-[#8D8D8D] text-xs mb-1 block">Details (optional)</label>
                <textarea
                  value={reportDetails}
                  onChange={e => setReportDetails(e.target.value)}
                  className="w-full bg-[#F5F5F5] rounded-xl px-4 py-2.5 text-[#111111] text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300] resize-none min-h-[60px]"
                  placeholder="Add more details..."
                  maxLength={500}
                />
                <p className="text-[#C7C7CC] text-[10px] text-right mt-0.5">{reportDetails.length}/500</p>
              </div>
              <button type="button" onClick={handleReportSubmit}
                disabled={!reportReason || processingAction}
                className="w-full bg-[#FF3B30] hover:bg-[#D32F2F] text-white rounded-xl py-3 text-sm font-bold transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {processingAction ? <Loader size={16} className="animate-spin" /> : <Flag size={16} />}
                Submit Report
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import type { PostPollData, Story, PostComment, TimelinePost } from '@/types';
import { useState, useRef, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Image, Plus, X, Loader, Globe, Users, Lock, RefreshCw, Camera, TrendingUp, Sparkles,
  Search, ArrowRight, Share2, Heart, Play, Hash, Film, Flame, List, Radio, Flag, Vote, Copy, Youtube
} from 'lucide-react';
import { useAuthStore } from '@/store/useAuthStore';
import { useFriendStore } from '@/store/useFriendStore';
import { useReelStore } from '@/store/useReelStore';
import {
  isFirestoreAvailable, COLLECTIONS, addDocToCollection,
  updateDocById, deleteDocById, subscribeToCollection, serverTimestamp
} from '@/lib/firestore';
import { where, orderBy, limit } from '@/lib/firestore';
import TimelineCard from '@/components/features/timeline/TimelineCard';
import BottomNav from '@/components/layout/BottomNav';
import EmptyState from '@/components/EmptyState';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AdBanner from '@/components/AdBanner';
import { MOCK_ADS } from '@/lib/mockAds';
import RequestTipModal from '@/components/RequestTipModal';
import FeedReelsViewer from '@/components/features/feed/FeedReelsViewer';
import YouTubeFeed from '@/components/features/feed/YouTubeFeed';
import { toast } from 'sonner';
import { getDefaultAvatar } from '@/lib/utils';

type Visibility = 'public' | 'friends' | 'private' | 'followers' | 'groups' | 'custom' | 'close_friends';

const visibilityOptions: { key: Visibility; label: string; icon: typeof Globe }[] = [
  { key: 'public', label: 'Public', icon: Globe },
  { key: 'friends', label: 'Friends', icon: Users },
  { key: 'private', label: 'Only Me', icon: Lock },
  { key: 'followers', label: 'Followers', icon: Users },
  { key: 'close_friends', label: 'Close Friends', icon: Users },
];

export default function TimelinePage() {
  const { user } = useAuthStore();
  const { friends, subscribeFriends, getSuggestedFriends } = useFriendStore();
  const { reels, getReels } = useReelStore();
  const navigate = useNavigate();

  const [posts, setPosts] = useState<TimelinePost[]>([]);
  const [loading, setLoading] = useState(true);
  const [showComposer, setShowComposer] = useState(false);
  const [content, setContent] = useState('');
  const [images, setImages] = useState<string[]>([]);
  const [visibility, setVisibility] = useState<Visibility>('public');
  const [uploading, setUploading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const refreshTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [feedFilter, setFeedFilter] = useState<'all' | 'public' | 'friends' | 'mine'>('all');
  const [postLimit, setPostLimit] = useState(20);

  const [postSearch, setPostSearch] = useState('');
  const [showPostSearch, setShowPostSearch] = useState(false);
  const [showImageViewer, setShowImageViewer] = useState(false);
  const [viewerImage, setViewerImage] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [sharePost, setSharePost] = useState<TimelinePost | null>(null);
  const [showPollComposer, setShowPollComposer] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState(['', '']);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportPost, setReportPost] = useState<TimelinePost | null>(null);
  const [reportReason, setReportReason] = useState('');
  const [dismissedAds, setDismissedAds] = useState<Set<string>>(new Set());
  const [showReelsStrip] = useState(true);
  const [showTrending] = useState(true);
  const [suggestedUsers, setSuggestedUsers] = useState<Array<{ id: string; name: string; avatar?: string; username?: string }>>([]);
  const [editingPost, setEditingPost] = useState<TimelinePost | null>(null);
  const [tipTarget, setTipTarget] = useState<{ userId: string; userName: string; userAvatar?: string; postId: string } | null>(null);

  // New posts indicator state
  const [lastSeenPostTime, setLastSeenPostTime] = useState<number>(Date.now());
  const [newPostsCount, setNewPostsCount] = useState(0);
  const [isAtTop, setIsAtTop] = useState(true);

  // Feed tab: 'feed' | 'reels' | 'stories' | 'videos'
  const [feedTab, setFeedTab] = useState<'feed' | 'reels' | 'stories' | 'videos'>('feed');
  const [showReelsViewer, setShowReelsViewer] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const storyFileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Real-time posts subscription
  useEffect(() => {
    if (!isFirestoreAvailable() || !user?.id) {
      setLoading(false);
      return;
    }
    setLoading(true);
    const unsub = subscribeToCollection(COLLECTIONS.POSTS, [orderBy('timestamp', 'desc'), limit(postLimit)], (data) => {
      const list: TimelinePost[] = (data || []).map((d: Record<string, unknown>) => ({
        id: d.id as string,
        userId: d.userId as string,
        content: (d.content as string) || '',
        images: (d.images as string[]) || [],
        likes: (d.likes as string[]) || [],
        comments: (d.comments as PostComment[]) || [],
        shares: (d.shares as string[]) || [],
        timestamp: (() => {
          const ts = d.timestamp;
          if (ts && typeof ts === 'object' && 'toDate' in ts && typeof (ts as { toDate(): Date }).toDate === 'function') {
            return (ts as { toDate(): Date }).toDate();
          }
          return new Date(ts as string | number);
        })(),
        visibility: (d.visibility as TimelinePost['visibility']) || 'public',
        pollData: (d.pollData as PostPollData) || undefined,
        userName: (d.userName as string) || (d.userId === user?.id ? user?.name : 'User'),
        userAvatar: (d.userAvatar as string) || (d.userId === user?.id ? user?.avatar : undefined),
      }));
      setPosts(list);
      setLoading(false);
    });
    return () => unsub();
  }, [user?.id, user?.name, user?.avatar, postLimit]);

  // Cleanup refresh timeout
  useEffect(() => {
    return () => {
      if (refreshTimeoutRef.current) clearTimeout(refreshTimeoutRef.current);
    };
  }, []);

  // Track scroll position and new posts
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const onScroll = () => {
      setIsAtTop(el.scrollTop < 50);
      if (el.scrollTop < 50 && newPostsCount > 0) {
        setNewPostsCount(0);
        setLastSeenPostTime(Date.now());
      }
    };
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => el.removeEventListener('scroll', onScroll);
  }, [newPostsCount]);

  // Detect new posts while scrolled down
  useEffect(() => {
    if (posts.length === 0 || isAtTop) {
      setLastSeenPostTime(Date.now());
      setNewPostsCount(0);
      return;
    }

    const newestPost = posts[0];
    const newestTime = newestPost.timestamp instanceof Date ? newestPost.timestamp.getTime() : new Date(newestPost.timestamp).getTime();

    if (newestTime > lastSeenPostTime) {
      const count = posts.filter(p => {
        const t = p.timestamp instanceof Date ? p.timestamp.getTime() : new Date(p.timestamp).getTime();
        return t > lastSeenPostTime;
      }).length;

      setNewPostsCount(count);

      // Signal: new timeline posts while user is not at top (keeps it real-time).
      if (count > 0) {
        import('@/lib/sounds')
          .then(({ safePlay, playTimelineNotification, vibrateNotification }) => {
            safePlay(playTimelineNotification, vibrateNotification);
          })
          .catch(() => {
            // ignore
          });
      }
    }
  }, [posts, isAtTop, lastSeenPostTime]);



  const handleScrollToTop = () => {
    scrollRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
    setNewPostsCount(0);
    setLastSeenPostTime(Date.now());
  };
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('share') === 'true') {
      setShowComposer(true);
      if ('caches' in window) {
        caches.match('/shared-data').then((response) => {
          if (response) {
            response.json().then((data) => {
              const text = [data.title, data.text, data.url].filter(Boolean).join(' ');
              if (text) setContent(text);
              caches.delete('/shared-data');
            }).catch(() => {});
          }
        }).catch(() => {});
      }
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  useEffect(() => {
    if (!user?.id) return;
    const unsub = subscribeFriends(user.id);
    return () => unsub();
  }, [user?.id, subscribeFriends]);

  // Fetch reels for the strip
  useEffect(() => {
    getReels(15);
  }, [getReels]);

  // Fetch suggested friends
  useEffect(() => {
    if (user?.id) {
      getSuggestedFriends(user.id).then((users) => {
        setSuggestedUsers(users.slice(0, 6));
      }).catch(() => {});
    }
  }, [user?.id, getSuggestedFriends]);

  // Real stories from Firestore with real-time subscription
  const [stories, setStories] = useState<Array<{ id: string; user_id: string; name: string; avatar: string | undefined; media_url: string; type: string; caption: string; isMine: boolean }>>([]);
  const [viewingStory, setViewingStory] = useState<typeof stories[number] | null>(null);
  const STORY_DURATION = 5000;
  const closeStory = () => setViewingStory(null);

  // Real-time stories subscription
  useEffect(() => {
    if (!isFirestoreAvailable() || !user?.id) return;
    const friendIds = friends.map(f => f.id);
    const allIds = [user.id, ...friendIds];
    const unsub = subscribeToCollection(COLLECTIONS.STORIES, [where('userId', 'in', allIds), orderBy('timestamp', 'desc')], (data) => {
      const list = (data || []).map((d: Record<string, unknown>) => ({
        id: d.id as string,
        user_id: d.userId as string,
        name: (d.userName as string) || (d.userId === user.id ? 'My Story' : 'Friend'),
        avatar: d.userAvatar as string | undefined,
        media_url: (d.mediaUrl as string) || '',
        type: (d.type as string) || 'image',
        caption: '',
        isMine: d.userId === user.id,
      }));
      setStories(list);
    });
    return () => unsub();
  }, [user?.id, friends]);

  // Auto-advance stories
  useEffect(() => {
    if (!viewingStory) return;
    const timer = setTimeout(() => {
      const idx = stories.indexOf(viewingStory);
      if (idx < stories.length - 1) {
        setViewingStory(stories[idx + 1]);
      } else {
        closeStory();
      }
    }, STORY_DURATION);
    return () => clearTimeout(timer);
  }, [viewingStory, stories]);

  const handleStoryUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user?.id) return;
    setUploading(true);
    try {
      const { uploadMediaBlob } = await import('@/lib/storage');
      const url = await uploadMediaBlob({ kind: 'stories', file, mimeType: file.type });
      await addDocToCollection(COLLECTIONS.STORIES, {
        userId: user.id,
        mediaUrl: url,
        type: file.type.startsWith('video') ? 'video' : 'image',
        viewedBy: [],
        timestamp: new Date().toISOString(),
      });
      toast.success('Story added!');
    } catch (err) {
      console.error(err);
      toast.error('Failed to upload story');
    } finally {
      setUploading(false);
      if (storyFileInputRef.current) storyFileInputRef.current.value = '';
    }
  };

  const handlePost = async () => {
    if (!user || (!content.trim() && images.length === 0 && !pollQuestion.trim())) return;
    setUploading(true);
    try {
      if (isFirestoreAvailable()) {
        const payload: Record<string, unknown> = {
          userId: user.id,
          content: content.trim(),
          images,
          likes: [],
          timestamp: serverTimestamp(),
          visibility,
          userName: user.name || '',
          userAvatar: user.avatar || '',
        };
        if (pollQuestion.trim() && pollOptions.filter(o => o.trim()).length >= 2) {
          payload.pollData = {
            question: pollQuestion.trim(),
            options: pollOptions.filter(o => o.trim()).map(o => ({ text: o.trim(), votes: [] })),
          };
        }
        await addDocToCollection(COLLECTIONS.POSTS, payload);
      }
      setContent('');
      setImages([]);
      setVisibility('public');
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowComposer(false);
      setShowPollComposer(false);
      toast.success('Post shared!');
    } catch {
      toast.error('Failed to post');
    } finally {
      setUploading(false);
    }
  };

  const handleEditPost = async () => {
    if (!editingPost || !user) return;
    try {
      if (isFirestoreAvailable()) {
        await updateDocById(COLLECTIONS.POSTS, editingPost.id, {
          content: content.trim(),
          visibility,
          images: editingPost.images || [],
        });
      }
      setContent('');
      setVisibility('public');
      setEditingPost(null);
      toast.success('Post updated');
    } catch {
      toast.error('Failed to update post');
    }
  };

  const handleDelete = async (postId: string) => {
    if (!isFirestoreAvailable()) return;
    try {
      await deleteDocById(COLLECTIONS.POSTS, postId);
      toast.success('Post deleted');
    } catch {
      toast.error('Failed to delete post');
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length + images.length > 4) {
      toast.error('Max 4 images per post');
      return;
    }
    setUploading(true);
    try {
      const { uploadMediaBlob } = await import('@/lib/storage');
      const urls: string[] = [];
      for (const file of files) {
        const url = await uploadMediaBlob({ kind: 'posts', file, mimeType: file.type });
        urls.push(url);
      }
      setImages(prev => [...prev, ...urls]);
    } catch {
      toast.error('Failed to upload images');
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const handleLike = async (postId: string) => {
    if (!user || !isFirestoreAvailable()) return;
    try {
      const post = posts.find(p => p.id === postId);
      if (!post) return;
      const liked = post.likes.includes(user.id);
      const newLikes = liked ? post.likes.filter(id => id !== user.id) : [...post.likes, user.id];
      await updateDocById(COLLECTIONS.POSTS, postId, { likes: newLikes });
      setPosts(prev => prev.map(p => p.id === postId ? { ...p, likes: newLikes } : p));
    } catch {
      toast.error('Failed to like post');
    }
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const handleComment = async (postId: string, commentText: string) => {
    if (!user || !isFirestoreAvailable() || !commentText.trim()) return;
    try {
      const post = posts.find(p => p.id === postId);
      if (!post) return;
      const newComments = [...(post.comments || []), {
        id: `c_${Date.now()}`,
        userId: user.id,
        content: commentText.trim(),
        timestamp: new Date(),
        likes: [],
        userName: user.name || '',
        userAvatar: user.avatar || '',
      }];
      await updateDocById(COLLECTIONS.POSTS, postId, { comments: newComments });
      setPosts(prev => prev.map(p => p.id === postId ? { ...p, comments: newComments } : p));
    } catch {
      toast.error('Failed to add comment');
    }
  };

  const handleShare = (post: TimelinePost) => {
    setSharePost(post);
    setShowShareModal(true);
  };

  const handleReport = (post: TimelinePost) => {
    setReportPost(post);
    setShowReportModal(true);
  };

  const submitReport = () => {
    if (!reportReason.trim() || !reportPost) return;
    toast.success('Report submitted. Thank you for helping keep GaGa Chat safe.');
    setReportReason('');
    setShowReportModal(false);
    setReportPost(null);
  };

  // Extract trending hashtags from posts
  const trendingTopics = useMemo(() => {
    const hashtagRegex = /#(\w+)/g;
    const counts = new Map<string, number>();
    posts.forEach(post => {
      const matches = post.content?.match(hashtagRegex);
      if (matches) {
        matches.forEach(tag => {
          counts.set(tag, (counts.get(tag) || 0) + 1);
        });
      }
    });
    return Array.from(counts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([tag]) => tag);
  }, [posts]);

  const filteredPosts = posts.filter(p => {
    if (feedFilter === 'public' && p.visibility !== 'public') return false;
    if (feedFilter === 'friends' && p.visibility !== 'friends') return false;
    if (feedFilter === 'mine' && p.userId !== user?.id) return false;
    if (postSearch) {
      const term = postSearch.toLowerCase();
      return (p.content || '').toLowerCase().includes(term) || (p.userName || '').toLowerCase().includes(term);
    }
    return true;
  });

  const hasMore = posts.length >= postLimit;

  const [loadingMore, setLoadingMore] = useState(false);

  const handleLoadMore = () => {
    if (loadingMore || !hasMore) return;
    setLoadingMore(true);
    setPostLimit(prev => prev + 20);
  };

  const handleLoadMoreRef = useRef(handleLoadMore);
  handleLoadMoreRef.current = handleLoadMore;

  // Auto-load more posts on scroll near bottom
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const onScroll = () => {
      if (loading || loadingMore || !hasMore) return;
      const { scrollTop, scrollHeight, clientHeight } = el;
      if (scrollTop + clientHeight >= scrollHeight - 200) {
        handleLoadMoreRef.current();
      }
    };
    el.addEventListener('scroll', onScroll);
    return () => el.removeEventListener('scroll', onScroll);
  }, [loading, loadingMore, hasMore]);

  // Reset loadingMore when posts update
  useEffect(() => {
    setLoadingMore(false);
  }, [posts.length]);

  const handleRefresh = async () => {
    if (refreshing) return;
    setRefreshing(true);
    setPostLimit(20);
    refreshTimeoutRef.current = setTimeout(() => setRefreshing(false), 1000);
  };

  // If showing full reels viewer, render it
  if (showReelsViewer) {
    return (
      <div className="h-full flex flex-col">
        <FeedReelsViewer onClose={() => setShowReelsViewer(false)} />
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-[#0d0d0d]">
      {/* Header with Tabs */}
      <div className="shrink-0 px-4 py-3 border-b border-[#1a1a1a]">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <h1 className="text-lg font-bold text-white">GaGa Feed</h1>
            <button type="button" onClick={handleRefresh} className="p-1.5 rounded-lg hover:bg-[#1a1a1a] text-[#8D8D8D]">
              <RefreshCw size={16} className={refreshing ? 'animate-spin' : ''} />
            </button>
          </div>
          <div className="flex items-center gap-2">
            <button type="button" onClick={() => setShowPostSearch(!showPostSearch)} className="p-2 rounded-lg hover:bg-[#1a1a1a] text-[#8D8D8D]">
              <Search size={18} />
            </button>
            <button type="button" onClick={() => { setShowComposer(true); setEditingPost(null); setContent(''); setImages([]); setVisibility('public'); }} className="p-2 rounded-lg bg-[#00C300] text-black hover:bg-[#00C300]/90">
              <Plus size={18} />
            </button>
          </div>
        </div>

        {/* Top-level tabs: Feed / Reels / Stories / Videos */}
        <div className="flex gap-2">
          {[
            { key: 'feed' as const, label: 'Feed', icon: Flame },
            { key: 'reels' as const, label: 'Reels', icon: Film },
            { key: 'stories' as const, label: 'Stories', icon: Radio },
            { key: 'videos' as const, label: 'Videos', icon: Youtube },
          ].map(t => {
            const Icon = t.icon;
            const isActive = feedTab === t.key;
            return (
              <button
                type="button"
                key={t.key}
                onClick={() => {
                  if (t.key === 'reels') {
                    setShowReelsViewer(true);
                  } else {
                    setFeedTab(t.key);
                  }
                }}
                className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-medium transition-all ${
                  isActive && t.key !== 'reels'
                    ? 'bg-[#00C300] text-black'
                    : t.key === 'reels'
                    ? 'bg-[#FF4081]/20 text-[#FF4081] hover:bg-[#FF4081]/30'
                    : t.key === 'videos'
                    ? 'bg-red-600/20 text-red-400 hover:bg-red-600/30'
                    : 'bg-[#1a1a1a] text-[#8D8D8D] hover:text-white'
                }`}
              >
                <Icon size={16} />
                {t.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Search bar */}
      <AnimatePresence>
        {showPostSearch && (
          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
            <div className="px-4 py-2 border-b border-[#1a1a1a]">
              <div className="relative">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8D8D8D]" />
                <input
                  type="text"
                  placeholder="Search posts..."
                  value={postSearch}
                  onChange={e => setPostSearch(e.target.value)}
                  className="w-full bg-[#1a1a1a] text-white pl-10 pr-4 py-2 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#00C300]"
                />
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Feed filter (only in feed tab) */}
      {feedTab === 'feed' && (
        <div className="shrink-0 flex gap-1 px-4 py-2 overflow-x-auto border-b border-[#1a1a1a]">
          {(['all', 'public', 'friends', 'mine'] as const).map(f => (
            <button type="button" key={f}
              onClick={() => setFeedFilter(f)}
              className={`px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap ${
                feedFilter === f ? 'bg-[#00C300] text-black' : 'bg-[#1a1a1a] text-[#8D8D8D]'
              }`}
            >
              {f === 'all' ? 'All' : f === 'public' ? 'Public' : f === 'friends' ? 'Friends' : 'My Posts'}
            </button>
          ))}
        </div>
      )}

      {/* Scrollable content */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto">
        {/* === STORIES TAB === */}
        {feedTab === 'stories' && (
          <div className="px-4 py-6 space-y-6">
            {/* Add story */}
            <div className="flex flex-col items-center gap-2 mb-6">
              <button
                type="button"
                onClick={() => storyFileInputRef.current?.click()}
                className="w-20 h-20 rounded-full border-2 border-dashed border-[#00C300] flex items-center justify-center bg-[#1a1a1a]"
              >
                <Camera size={28} className="text-[#00C300]" />
              </button>
              <span className="text-[#8D8D8D] text-xs">Add Story</span>
              <input type="file" ref={storyFileInputRef} accept="image/*,video/*" className="hidden" onChange={handleStoryUpload} />
            </div>

            {/* Stories grid */}
            {stories.length === 0 ? (
              <EmptyState icon={Camera} title="No stories yet" description="Add your first story to share with friends!" />
            ) : (
              <div className="grid grid-cols-3 gap-3">
                {stories.map(story => (
                  <button
                    type="button"
                    key={story.id}
                    onClick={() => setViewingStory(story)}
                    className="relative aspect-[3/4] rounded-xl overflow-hidden group"
                  >
                    {story.type === 'video' ? (
                      <video src={story.media_url} className="w-full h-full object-cover" muted />
                    ) : (
                      <img src={story.media_url} alt="Story" className="w-full h-full object-cover" />
                    )}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />
                    <div className="absolute top-2 left-2">
                      <div className={`w-8 h-8 rounded-full p-0.5 ${story.isMine ? 'bg-[#00C300]' : 'bg-gradient-to-tr from-[#00C300] to-[#00FF00]'}`}>
                        <img src={story.avatar || getDefaultAvatar(story.user_id)} alt="" className="w-full h-full rounded-full object-cover bg-[#1a1a1a]" />
                      </div>
                    </div>
                    <div className="absolute bottom-2 left-2 right-2">
                      <p className="text-white text-xs font-medium truncate">{story.name}</p>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {/* === FEED TAB === */}
        {feedTab === 'feed' && (
          <>
            {/* Stories Strip */}
            <div className="shrink-0 px-4 py-3">
              <div className="flex gap-3 overflow-x-auto pb-2">
                {/* Add story */}
                <button type="button" onClick={() => storyFileInputRef.current?.click()} className="shrink-0 flex flex-col items-center gap-1">
                  <div className="w-16 h-16 rounded-full border-2 border-dashed border-[#00C300] flex items-center justify-center bg-[#1a1a1a]">
                    <Camera size={20} className="text-[#00C300]" />
                  </div>
                  <span className="text-[10px] text-[#8D8D8D]">Add Story</span>
                </button>
                {stories.map(story => (
                  <button type="button" key={story.id} onClick={() => setViewingStory(story)} className="shrink-0 flex flex-col items-center gap-1">
                    <div className={`w-16 h-16 rounded-full p-0.5 ${story.isMine ? 'bg-[#00C300]' : 'bg-gradient-to-tr from-[#00C300] to-[#00FF00]'}`}>
                      <img src={story.avatar || getDefaultAvatar(story.user_id)} alt={story.name} className="w-full h-full rounded-full object-cover bg-[#1a1a1a]" />
                    </div>
                    <span className="text-[10px] text-[#8D8D8D] truncate max-w-[64px]">{story.name}</span>
                  </button>
                ))}
              </div>
              <input type="file" ref={storyFileInputRef} accept="image/*,video/*" className="hidden" onChange={handleStoryUpload} />
            </div>

            {/* Reels Strip */}
            {reels.length > 0 && showReelsStrip && (
              <div className="shrink-0 px-4 py-2 border-b border-[#1a1a1a]">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <Film size={16} className="text-[#FF4081]" />
                    <h2 className="text-sm font-semibold text-white">Reels</h2>
                  </div>
                  <button type="button" onClick={() => setShowReelsViewer(true)} className="text-xs text-[#FF4081] flex items-center gap-1">
                    Watch all <ArrowRight size={12} />
                  </button>
                </div>
                <div className="flex gap-2 overflow-x-auto pb-2">
                  {reels.slice(0, 10).map((reel) => (
                    <button
                      type="button"
                      key={reel.id}
                      onClick={() => setShowReelsViewer(true)}
                      className="shrink-0 relative w-28 h-40 rounded-xl overflow-hidden group"
                    >
                      {reel.thumbnailUrl ? (
                        <img
                          src={reel.thumbnailUrl}
                          alt={reel.caption || 'Reel'}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                        />
                      ) : (
                        <div className="w-full h-full bg-gradient-to-br from-[#1a1a1a] to-[#0d0d0d] flex items-center justify-center">
                          <Play size={24} className="text-white/50" />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" />
                      <div className="absolute bottom-2 left-2 right-2">
                        <p className="text-white text-xs font-medium truncate">{reel.userName || 'User'}</p>
                        <p className="text-white/70 text-[10px] truncate">{reel.caption || 'Reel'}</p>
                      </div>
                      <div className="absolute top-2 right-2">
                        <div className="flex items-center gap-0.5 bg-black/50 rounded-full px-1.5 py-0.5">
                          <Play size={8} className="text-white" />
                          <span className="text-white text-[10px]">{reel.viewCount || 0}</span>
                        </div>
                      </div>
                    </button>
                  ))}
                  <button
                    type="button"
                    onClick={() => navigate('/create-reel')}
                    className="shrink-0 w-28 h-40 rounded-xl border border-dashed border-[#FF4081] flex flex-col items-center justify-center gap-2 hover:border-[#FF4081]/80 hover:bg-[#FF4081]/5 transition-colors"
                  >
                    <Plus size={24} className="text-[#FF4081]" />
                    <span className="text-[#FF4081] text-xs font-medium">Create Reel</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => setShowReelsViewer(true)}
                    className="shrink-0 w-28 h-40 rounded-xl border border-dashed border-[#8D8D8D] flex flex-col items-center justify-center gap-2 hover:border-[#00C300] transition-colors"
                  >
                    <Play size={24} className="text-[#8D8D8D]" />
                    <span className="text-[#8D8D8D] text-xs">Watch all</span>
                  </button>
                </div>
              </div>
            )}

            {/* Trending Topics */}
            {trendingTopics.length > 0 && showTrending && !postSearch && (
              <div className="shrink-0 px-4 py-2 border-b border-[#1a1a1a]">
                <div className="flex items-center gap-2 mb-2">
                  <TrendingUp size={14} className="text-[#00C300]" />
                  <h2 className="text-xs font-semibold text-[#8D8D8D] uppercase tracking-wider">Trending</h2>
                </div>
                <div className="flex gap-2 overflow-x-auto pb-1">
                  {trendingTopics.map(tag => (
                    <button
                      type="button"
                      key={tag}
                      onClick={() => { setPostSearch(tag); setShowPostSearch(true); }}
                      className="shrink-0 px-3 py-1.5 rounded-full bg-[#1a1a1a] text-[#00C300] text-xs font-medium hover:bg-[#00C300]/10 transition-colors flex items-center gap-1"
                    >
                      <Hash size={10} /> {tag.replace('#', '')}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Quick composer hint */}
            {!showComposer && user && (
              <div className="shrink-0 px-4 py-3 border-b border-[#1a1a1a]">
                <button
                  type="button"
                  onClick={() => { setShowComposer(true); setEditingPost(null); setContent(''); setImages([]); }}
                  className="w-full flex items-center gap-3 bg-[#1a1a1a] rounded-xl px-4 py-3 hover:bg-[#222] transition-colors"
                >
                  <img src={user.avatar || getDefaultAvatar(user.id)} alt="User avatar" className="w-9 h-9 rounded-full object-cover shrink-0" />
                  <span className="text-[#8D8D8D] text-sm flex-1 text-left">What's on your mind?</span>
                  <div className="flex items-center gap-2">
                    <Image size={18} className="text-[#8D8D8D]" />
                    <Plus size={18} className="text-[#8D8D8D]" />
                  </div>
                </button>
              </div>
            )}

            {/* Loading */}
            {loading && posts.length === 0 && <LoadingSkeleton />}

            {/* Suggested Friends - when no posts or few posts */}
            {!loading && filteredPosts.length < 3 && suggestedUsers.length > 0 && (
              <div className="shrink-0 px-4 py-4 border-b border-[#1a1a1a]">
                <div className="flex items-center justify-between mb-3">
                  <h2 className="text-sm font-semibold text-white">Suggested for you</h2>
                  <button type="button" onClick={() => navigate('/add-friends')} className="text-xs text-[#00C300]">See all</button>
                </div>
                <div className="flex gap-3 overflow-x-auto pb-2">
                  {suggestedUsers.map(su => (
                    <div key={su.id} className="shrink-0 w-32 bg-[#1a1a1a] rounded-xl p-3 flex flex-col items-center gap-2">
                      <img src={su.avatar || getDefaultAvatar(su.id)} alt="User avatar" className="w-12 h-12 rounded-full object-cover" />
                      <p className="text-white text-xs font-medium truncate w-full text-center">{su.name}</p>
                      <p className="text-[#8D8D8D] text-[10px] truncate w-full text-center">@{su.username || 'user'}</p>
                      <button
                        type="button"
                        onClick={() => navigate('/add-friends')}
                        className="w-full py-1.5 rounded-full bg-[#00C300] text-black text-xs font-medium hover:bg-[#00C300]/90"
                      >
                        Follow
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Empty state */}
            {!loading && filteredPosts.length === 0 && (
              <EmptyState icon={List} title="No posts yet" description="Be the first to share something!" />
            )}

            {/* Posts */}
            {!loading && filteredPosts.map((post, index) => (
              <div key={post.id}>
                <TimelineCard
                  post={post}
                  index={index}
                  onShare={() => handleShare(post)}
                  onEdit={() => { setEditingPost(post); setContent(post.content); setImages(post.images || []); setVisibility(post.visibility); setShowComposer(true); }}
                  onDelete={() => handleDelete(post.id)}
                  onImageClick={(url: string) => { setViewerImage(url); setShowImageViewer(true); }}
                  onTip={() => setTipTarget({ userId: post.userId, userName: post.userName || 'User', userAvatar: post.userAvatar, postId: post.id })}
                  onReport={() => handleReport(post)}
                  userName={post.userName}
                  userAvatar={post.userAvatar}
                />
                {index > 0 && index % 3 === 0 && !dismissedAds.has('timeline_' + index) && (
                  <div className="px-4">
                    <AdBanner
                      {...MOCK_ADS[0]}
                      onDismiss={() => setDismissedAds(prev => new Set([...prev, 'timeline_' + index]))}
                      variant="compact"
                    />
                  </div>
                )}
              </div>
            ))}

            {/* Load More */}
            {!loading && !loadingMore && filteredPosts.length > 0 && hasMore && (
              <div className="flex justify-center py-4">
                <button
                  type="button"
                  onClick={handleLoadMore}
                  className="px-6 py-2 rounded-full bg-[#1a1a1a] text-[#8D8D8D] text-sm font-medium hover:bg-[#222] transition-colors"
                >
                  Load more posts
                </button>
              </div>
            )}
            {loadingMore && (
              <div className="flex justify-center py-4">
                <Loader size={18} className="animate-spin text-[#00C300]" />
              </div>
            )}

            {/* End of feed indicator */}
            {!loading && filteredPosts.length > 0 && !hasMore && (
              <div className="flex flex-col items-center py-6 gap-2">
                <div className="w-8 h-8 rounded-full bg-[#1a1a1a] flex items-center justify-center">
                  <Sparkles size={14} className="text-[#8D8D8D]" />
                </div>
                <p className="text-[#8D8D8D] text-xs">You're all caught up!</p>
              </div>
            )}
          </>
        )}

        {/* === VIDEOS TAB === */}
        {feedTab === 'videos' && (
          <YouTubeFeed />
        )}
      </div>

      {/* Bottom nav */}
      <BottomNav />

      {/* Story viewer with progress bar and tap navigation */}
      <AnimatePresence>
        {viewingStory && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black flex flex-col"
          >
            {/* Progress bar */}
            <div className="absolute top-0 left-0 right-0 z-10 flex gap-1 px-2 pt-2">
              {stories.map((story, idx) => {
                const currentIdx = stories.indexOf(viewingStory);
                const isActive = idx === currentIdx;
                const isPast = idx < currentIdx;
                return (
                  <div key={story.id} className="flex-1 h-1 bg-white/30 rounded-full overflow-hidden">
                    <motion.div
                      className="h-full bg-white rounded-full"
                      initial={{ width: isPast ? '100%' : '0%' }}
                      animate={{ width: isActive ? '100%' : isPast ? '100%' : '0%' }}
                      transition={isActive ? { duration: STORY_DURATION / 1000, ease: 'linear' } : { duration: 0.3 }}
                    />
                  </div>
                );
              })}
            </div>

            {/* Header */}
            <div className="flex items-center justify-between p-4 pt-6 z-10">
              <div className="flex items-center gap-2">
                <img src={viewingStory.avatar || getDefaultAvatar(viewingStory.user_id)} alt="User avatar" className="w-8 h-8 rounded-full" />
                <span className="text-white text-sm font-medium">{viewingStory.name}</span>
                {viewingStory.isMine && (
                  <span className="text-[10px] bg-white/20 text-white px-2 py-0.5 rounded-full">{stories.filter(s => s.user_id === viewingStory.user_id).length} views</span>
                )}
              </div>
              <button type="button" onClick={closeStory} className="text-white"><X size={24} /></button>
            </div>

            {/* Story content with tap zones */}
            <div className="flex-1 relative flex items-center justify-center">
              {/* Left tap zone (previous) */}
              <button
                type="button"
                className="absolute left-0 top-0 bottom-0 w-1/3 z-10"
                onClick={() => {
                  const idx = stories.indexOf(viewingStory);
                  if (idx > 0) setViewingStory(stories[idx - 1]);
                  else closeStory();
                }}
                aria-label="Previous story"
              />
              {/* Right tap zone (next) */}
              <button
                type="button"
                className="absolute right-0 top-0 bottom-0 w-1/3 z-10"
                onClick={() => {
                  const idx = stories.indexOf(viewingStory);
                  if (idx < stories.length - 1) setViewingStory(stories[idx + 1]);
                  else closeStory();
                }}
                aria-label="Next story"
              />
              {viewingStory.type === 'video' ? (
                <video src={viewingStory.media_url} className="max-w-full max-h-full" controls autoPlay />
              ) : (
                <img src={viewingStory.media_url} alt="Post image" className="max-w-full max-h-full object-contain" />
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* New Posts floating indicator */}
      <AnimatePresence>
        {newPostsCount > 0 && !isAtTop && feedTab === 'feed' && (
          <motion.button
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            onClick={handleScrollToTop}
            className="fixed top-20 left-1/2 -translate-x-1/2 z-40 flex items-center gap-2 px-4 py-2 bg-[#00C300] text-black rounded-full shadow-lg font-medium text-sm hover:bg-[#00A300] transition-colors"
          >
            <RefreshCw size={14} className="animate-spin" />
            {newPostsCount} new post{newPostsCount > 1 ? 's' : ''}
          </motion.button>
        )}
      </AnimatePresence>

      {/* Image viewer */}
      <AnimatePresence>
        {showImageViewer && viewerImage && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center p-4"
            onClick={() => setShowImageViewer(false)}
          >
            <button type="button" className="absolute top-4 right-4 text-white"><X size={28} /></button>
            <img src={viewerImage} alt="Image" className="max-w-full max-h-full object-contain rounded-lg" />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Share modal */}
      <AnimatePresence>
        {showShareModal && sharePost && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center"
            onClick={() => setShowShareModal(false)}
          >
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
              className="bg-[#1a1a1a] rounded-t-2xl sm:rounded-2xl p-6 w-full max-w-sm"
              onClick={e => e.stopPropagation()}
            >
              <h3 className="text-white font-semibold mb-4">Share Post</h3>
              <div className="flex flex-col gap-3">
                <button type="button" onClick={() => {
                    navigator.clipboard.writeText(`https://gagachat.app/post/${sharePost.id}`);
                    toast.success('Link copied!');
                    setShowShareModal(false);
                  }}
                  className="flex items-center gap-3 p-3 rounded-xl bg-[#2a2a2a] text-white hover:bg-[#333]"
                >
                  <Copy size={18} /> Copy Link
                </button>
                <button type="button" onClick={() => {
                    if (navigator.share) {
                      navigator.share({ title: 'GaGa Chat Post', text: sharePost.content || 'Check out this post', url: `https://gagachat.app/post/${sharePost.id}` });
                    } else {
                      navigator.clipboard.writeText(`https://gagachat.app/post/${sharePost.id}`);
                      toast.success('Link copied!');
                    }
                    setShowShareModal(false);
                  }}
                  className="flex items-center gap-3 p-3 rounded-xl bg-[#2a2a2a] text-white hover:bg-[#333]"
                >
                  <Share2 size={18} /> Share via...
                </button>
                <button type="button" onClick={() => {
                    toast.success('Post saved to your bookmarks');
                    setShowShareModal(false);
                  }}
                  className="flex items-center gap-3 p-3 rounded-xl bg-[#2a2a2a] text-white hover:bg-[#333]"
                >
                  <Heart size={18} /> Save to Bookmarks
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Post composer */}
      <AnimatePresence>
        {showComposer && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center"
            onClick={() => { setShowComposer(false); setEditingPost(null); }}
          >
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
              className="bg-[#1a1a1a] rounded-t-2xl sm:rounded-2xl p-4 w-full max-w-lg max-h-[90vh] overflow-y-auto"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-white font-semibold">{editingPost ? 'Edit Post' : 'New Post'}</h3>
                <button type="button" onClick={() => { setShowComposer(false); setEditingPost(null); }} className="text-[#8D8D8D]"><X size={20} /></button>
              </div>

              {/* User preview */}
              {user && (
                <div className="flex items-center gap-2 mb-3">
                  <img src={user.avatar || getDefaultAvatar(user.id)} alt="User avatar" className="w-8 h-8 rounded-full object-cover" />
                  <div>
                    <p className="text-white text-sm font-medium">{user.name}</p>
                    <div className="flex items-center gap-1">
                      {visibilityOptions.map(opt => (
                        <button
                          type="button"
                          key={opt.key}
                          onClick={() => setVisibility(opt.key)}
                          className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] ${
                            visibility === opt.key ? 'bg-[#00C300] text-black' : 'bg-[#2a2a2a] text-[#8D8D8D]'
                          }`}
                        >
                          <opt.icon size={8} /> {opt.label}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              <textarea
                value={content}
                onChange={e => setContent(e.target.value)}
                placeholder="What's on your mind?"
                className="w-full bg-[#2a2a2a] text-white rounded-xl p-3 min-h-[100px] resize-none focus:outline-none focus:ring-2 focus:ring-[#00C300]"
              />
              {/* Images */}
              {images.length > 0 && (
                <div className="flex gap-2 mt-3 overflow-x-auto">
                  {images.map((img, i) => (
                    <div key={i} className="relative shrink-0">
                      <img src={img} alt="Cover image" className="w-20 h-20 rounded-lg object-cover" />
                      <button type="button" onClick={() => setImages(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-1 -right-1 bg-red-500 rounded-full p-0.5"><X size={12} /></button>
                    </div>
                  ))}
                </div>
              )}
              {/* Poll composer */}
              {showPollComposer && (
                <div className="mt-3 bg-[#2a2a2a] rounded-xl p-3 space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-white text-sm font-medium flex items-center gap-2"><Vote size={14} /> Poll</span>
                    <button type="button" onClick={() => { setShowPollComposer(false); setPollQuestion(''); setPollOptions(['', '']); }} className="text-[#8D8D8D] hover:text-white"><X size={14} /></button>
                  </div>
                  <input
                    type="text"
                    value={pollQuestion}
                    onChange={e => setPollQuestion(e.target.value)}
                    placeholder="Ask a question..."
                    className="w-full bg-[#1a1a1a] text-white rounded-lg px-3 py-2 text-sm placeholder:text-[#8D8D8D] focus:outline-none focus:ring-2 focus:ring-[#00C300]"
                  />
                  {pollOptions.map((opt, i) => (
                    <div key={i} className="flex gap-2">
                      <input
                        type="text"
                        value={opt}
                        onChange={e => {
                          const next = [...pollOptions];
                          next[i] = e.target.value;
                          setPollOptions(next);
                        }}
                        placeholder={`Option ${i + 1}`}
                        className="flex-1 bg-[#1a1a1a] text-white rounded-lg px-3 py-2 text-sm placeholder:text-[#8D8D8D] focus:outline-none focus:ring-2 focus:ring-[#00C300]"
                      />
                      {pollOptions.length > 2 && (
                        <button type="button" onClick={() => setPollOptions(prev => prev.filter((_, idx) => idx !== i))} className="text-[#FF3B30] px-2"><X size={14} /></button>
                      )}
                    </div>
                  ))}
                  {pollOptions.length < 4 && (
                    <button type="button" onClick={() => setPollOptions(prev => [...prev, ''])} className="text-xs text-[#00C300] font-medium">+ Add option</button>
                  )}
                </div>
              )}
              {/* Actions */}
              <div className="flex items-center justify-between mt-4">
                <div className="flex items-center gap-1">
                  <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 rounded-lg hover:bg-[#2a2a2a] text-[#8D8D8D]" title="Add image">
                    <Image size={20} />
                  </button>
                  <button type="button" onClick={() => setShowPollComposer(!showPollComposer)} className={`p-2 rounded-lg hover:bg-[#2a2a2a] ${showPollComposer ? 'text-[#00C300]' : 'text-[#8D8D8D]'}`} title="Add poll">
                    <Vote size={20} />
                  </button>
                </div>
                <button type="button" onClick={editingPost ? handleEditPost : handlePost}
                  disabled={uploading || (!content.trim() && images.length === 0 && !(showPollComposer && pollQuestion.trim() && pollOptions.filter(o => o.trim()).length >= 2))}
                  className="px-6 py-2 rounded-xl bg-[#00C300] text-black font-medium disabled:opacity-50"
                >
                  {uploading ? <Loader size={18} className="animate-spin" /> : editingPost ? 'Update' : 'Post'}
                </button>
              </div>
              <input type="file" ref={fileInputRef} accept="image/*" multiple className="hidden" onChange={handleImageUpload} />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Report Modal */}
      <AnimatePresence>
        {showReportModal && reportPost && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center"
            onClick={() => setShowReportModal(false)}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              className="bg-[#1a1a1a] rounded-t-2xl sm:rounded-2xl p-6 w-full max-w-sm"
              onClick={e => e.stopPropagation()}
            >
              <h3 className="text-white font-semibold mb-1 flex items-center gap-2"><Flag size={18} className="text-[#FF3B30]" /> Report Post</h3>
              <p className="text-[#8D8D8D] text-xs mb-4">Help us keep GaGa Chat safe by reporting inappropriate content.</p>
              <div className="space-y-2 mb-4">
                {['Spam', 'Harassment or bullying', 'Violence or harmful content', 'Misinformation', 'Other'].map(reason => (
                  <button
                    type="button"
                    key={reason}
                    onClick={() => setReportReason(reason)}
                    className={`w-full text-left px-3 py-2.5 rounded-xl text-sm transition-colors ${
                      reportReason === reason ? 'bg-[#FF3B30]/20 text-white' : 'bg-[#2a2a2a] text-[#8D8D8D] hover:bg-[#333]'
                    }`}
                  >
                    {reason}
                  </button>
                ))}
              </div>
              <div className="flex gap-3">
                <button type="button" onClick={() => setShowReportModal(false)} className="flex-1 py-3 bg-[#2a2a2a] text-white rounded-xl text-sm font-bold">Cancel</button>
                <button type="button" onClick={submitReport} disabled={!reportReason} className="flex-1 py-3 bg-[#FF3B30] text-white rounded-xl text-sm font-bold disabled:opacity-50">Report</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Tip Modal */}
      <RequestTipModal
        open={!!tipTarget}
        onClose={() => setTipTarget(null)}
        toUserId={tipTarget?.userId || ''}
        toUserName={tipTarget?.userName}
        toUserAvatar={tipTarget?.userAvatar}
        contentId={tipTarget?.postId}
        contentType="post"
      />
    </div>
  );
}

